/*
  pingoscope — SENDER (Waveshare ESP32-S3-ETH)
  W5500 DHCP + 1Hz ping 8.8.8.8 (MSG_PROBE) + ip-api public IP/city/region/country/ASN
  every 5s (MSG_NETINFO), all over ESP-NOW. No libraries to install.
  Board: ESP32S3 Dev Module (verify log says ...:esp32s3) · USB CDC On Boot: Enabled
*/
#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>
#include <SPI.h>
#include <ETH.h>
#include <HTTPClient.h>
#include "ping/ping_sock.h"
#include "lwip/ip_addr.h"

#define RGB_PIN 21
#define ETH_TYPE ETH_PHY_W5500
#define ETH_ADDR 1
#define ETH_CS 14
#define ETH_IRQ 10
#define ETH_RST 9
#define ETH_SCK 13
#define ETH_MISO 12
#define ETH_MOSI 11

#define ESPNOW_CHANNEL 1
uint8_t PEER_MAC[6] = { 0x70, 0x4B, 0xCA, 0x7B, 0x95, 0xEC };
#define NETINFO_EVERY_MS 5000

#define MSG_PROBE   1
#define MSG_NETINFO 2

typedef struct __attribute__((packed)) {
  uint8_t type; uint32_t seq; uint16_t rtt_ms; uint8_t status;
} probe_t;
typedef struct __attribute__((packed)) {
  uint8_t type; char ip[16]; char cc[4]; char city[24]; char region[24]; char country[32]; char asn[40];
} netinfo_t;

uint32_t seq = 0;
netinfo_t net;

static SemaphoreHandle_t ping_done;
static volatile uint32_t ping_rtt = 0;
static volatile bool     ping_ok  = false;
static void ping_success(esp_ping_handle_t h, void *a){ uint32_t t; esp_ping_get_profile(h,ESP_PING_PROF_TIMEGAP,&t,sizeof(t)); ping_rtt=t; ping_ok=true; }
static void ping_timeout(esp_ping_handle_t h, void *a){ ping_ok=false; }
static void ping_end(esp_ping_handle_t h, void *a){ esp_ping_delete_session(h); xSemaphoreGive(ping_done); }
bool pingOnce(uint16_t &rttOut){
  ip_addr_t t; memset(&t,0,sizeof(t)); ipaddr_aton("8.8.8.8",&t);
  esp_ping_config_t cfg = ESP_PING_DEFAULT_CONFIG();
  cfg.target_addr=t; cfg.count=1; cfg.timeout_ms=1000;
  esp_ping_callbacks_t cbs={}; cbs.on_ping_success=ping_success; cbs.on_ping_timeout=ping_timeout; cbs.on_ping_end=ping_end;
  ping_ok=false; ping_rtt=0;
  esp_ping_handle_t h;
  if (esp_ping_new_session(&cfg,&cbs,&h)!=ESP_OK) return false;
  esp_ping_start(h);
  xSemaphoreTake(ping_done, pdMS_TO_TICKS(1500));
  rttOut = ping_rtt>65535?65535:(uint16_t)ping_rtt;
  return ping_ok;
}

void setLed(uint8_t s){
  switch(s){ case 0:neopixelWrite(RGB_PIN,0,40,0);break; case 1:neopixelWrite(RGB_PIN,50,15,0);break;
             case 2:neopixelWrite(RGB_PIN,40,30,0);break; default:neopixelWrite(RGB_PIN,40,0,0);break; }
}

#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(4,0,0)
void onDataSent(const wifi_tx_info_t *info, esp_now_send_status_t st){
#else
void onDataSent(const uint8_t *mac, esp_now_send_status_t st){
#endif
  if (st!=ESP_NOW_SEND_SUCCESS) Serial.println("  (espnow: no ACK)");
}

String jsonStr(const String &s, const char *key){
  String pat = String("\"")+key+"\":\""; int i=s.indexOf(pat);
  if (i<0) return ""; i+=pat.length(); int j=s.indexOf('"',i);
  return j<0 ? "" : s.substring(i,j);
}

void fetchNetInfo(){
  HTTPClient http;
  http.begin("http://ip-api.com/json/?fields=query,countryCode,city,regionName,country,as");
  int code = http.GET();
  if (code==200){
    String b = http.getString();
    net.type=MSG_NETINFO;
    strncpy(net.ip,      jsonStr(b,"query").c_str(),       sizeof(net.ip)-1);      net.ip[sizeof(net.ip)-1]=0;
    strncpy(net.cc,      jsonStr(b,"countryCode").c_str(), sizeof(net.cc)-1);      net.cc[sizeof(net.cc)-1]=0;
    strncpy(net.city,    jsonStr(b,"city").c_str(),        sizeof(net.city)-1);    net.city[sizeof(net.city)-1]=0;
    strncpy(net.region,  jsonStr(b,"regionName").c_str(),  sizeof(net.region)-1);  net.region[sizeof(net.region)-1]=0;
    strncpy(net.country, jsonStr(b,"country").c_str(),     sizeof(net.country)-1); net.country[sizeof(net.country)-1]=0;
    strncpy(net.asn,     jsonStr(b,"as").c_str(),          sizeof(net.asn)-1);     net.asn[sizeof(net.asn)-1]=0;
    esp_now_send(PEER_MAC,(uint8_t*)&net,sizeof(net));
    Serial.printf("netinfo: %s %s %s / %s\n", net.ip, net.cc, net.city, net.asn);
  } else Serial.printf("ip-api HTTP %d\n", code);
  http.end();
}

void setup(){
  Serial.begin(115200); delay(300);
  neopixelWrite(RGB_PIN,30,30,30);
  ping_done = xSemaphoreCreateBinary();

  WiFi.mode(WIFI_STA); WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);
  Serial.print("Sender MAC: "); Serial.println(WiFi.macAddress());
  if (esp_now_init()!=ESP_OK){ Serial.println("espnow init fail"); return; }
  esp_now_register_send_cb(onDataSent);
  esp_now_peer_info_t peer={}; memcpy(peer.peer_addr,PEER_MAC,6); peer.channel=ESPNOW_CHANNEL; peer.encrypt=false;
  esp_now_add_peer(&peer);

  SPI.begin(ETH_SCK,ETH_MISO,ETH_MOSI);
  ETH.begin(ETH_TYPE,ETH_ADDR,ETH_CS,ETH_IRQ,ETH_RST,SPI);
  Serial.println("Ethernet starting...");
}

bool ipPrinted=false;
unsigned long lastNetInfo=0;

void loop(){
  unsigned long t0=millis();
  probe_t pkt; pkt.type=MSG_PROBE; pkt.seq=seq++; pkt.rtt_ms=0;
  bool haveIp=false;

  if (!ETH.linkUp()){ pkt.status=3; ipPrinted=false; }
  else if (ETH.localIP()==IPAddress((uint32_t)0)){ pkt.status=2; }
  else {
    haveIp=true;
    if(!ipPrinted){ Serial.print("Got IP: "); Serial.println(ETH.localIP()); ipPrinted=true; }
    uint16_t rtt;
    if (pingOnce(rtt)){ pkt.status=0; pkt.rtt_ms=rtt; } else pkt.status=1;
  }

  setLed(pkt.status);
  esp_now_send(PEER_MAC,(uint8_t*)&pkt,sizeof(pkt));
  Serial.printf("seq=%lu status=%u rtt=%u\n",(unsigned long)pkt.seq,pkt.status,pkt.rtt_ms);

  if (haveIp && (lastNetInfo==0 || millis()-lastNetInfo>=NETINFO_EVERY_MS)){
    lastNetInfo=millis(); fetchNetInfo();
  }

  unsigned long el=millis()-t0;
  if (el<1000) delay(1000-el);
}
